-- ============================================================
-- Instinctive Fire's buff needs a family flag to be modifiable
-- ============================================================
--
-- Without this the +3/6 sec above silently does NOTHING, with no error.
-- Player::IsAffectedBySpellMod requires `spellmod->mask & spellInfo->
-- SpellFamilyFlags` to be non-zero, and Aura::CalcMaxDuration applies
-- SPELLMOD_DURATION against the aura's OWN spell -- which is 200742, the buff,
-- not 1462, the shot.  200742 shipped with SpellFamilyName 9 but all three
-- family flag words zero, so no mask could ever match it.
--
-- This is the same trap 1462 hit during the Beast Mastery pass, one spell
-- along: the shot was given word2 bit21 so Invigoration could modify it, and
-- nobody noticed the BUFF had no bit at all because nothing modified it yet.
--
-- Bit 22 of word 2 (4194304), NOT bit 21.  Reusing the shot's bit would make
-- Invigoration's free-cast cost modifier (200757) match the buff as well as the
-- shot, and a charge-limited modifier that matches two spells is consumed by
-- whichever the engine reaches first.  Bit 22 was verified free by scanning
-- every family-9 record in Spell.dbc: no spell carries it as a flag, and no
-- effect anywhere masks it.
--
-- UPDATE, not a re-INSERT: 200742's full row lives in woa_2026_08_11_03.sql,
-- which sorts earlier, so this lands on top of it.

UPDATE `alonecraft_spell_dbc` SET `SpellFamilyFlags2` = 4194304 WHERE `ID` = 200742;

-- ============================================================
-- Lethal Instincts: proc configuration
-- ============================================================
--
-- Two rows rather than one negative row, because the 50/100% split lives in
-- spell_proc.Chance, which is keyed by spell id.
--
-- SpellFamilyMask0 133120 = Arcane Shot (0x800) | Aimed Shot (0x20000).
-- SpellFamilyMask1 1      = Steady Shot.
-- SpellFamilyMask2 1      = Chimera Shot.
--
-- ProcFlags 256 = PROC_FLAG_DONE_SPELL_RANGED_DMG_CLASS (SpellMgr.h:122).
--
-- SpellPhaseMask 2 (PROC_SPELL_PHASE_HIT) is load-bearing: a row with phase 0
-- silently never triggers.
--
-- AttributesMask 0 is correct here.  All four shots are real player casts, so
-- Aura::IsProcTriggeredOnEvent's triggered-spell filter (SpellAuras.cpp:2152)
-- never rejects them and PROC_ATTR_TRIGGERED_CAN_PROC is not needed.
--
-- The DBC ProcChance on 19407/19412 is set to 50/100 to match, because $h in
-- the talent description reads the DBC value, NOT spell_proc.Chance.  The two
-- are independent and nothing but reading the tooltip catches a mismatch.

DELETE FROM `spell_proc` WHERE `SpellId` IN (19407, 19412);
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(19407, 0, 9, 133120, 1, 1, 256, 0, 2, 0, 0, 0, 0, 50, 0, 0),
(19412, 0, 9, 133120, 1, 1, 256, 0, 2, 0, 0, 0, 0, 100, 0, 0);

